class AsyncOrderApi(_gen.AsyncSectionApi):
    """The operations of the order section, for AsyncClient: ``client.order``.

    The methods of OrderApi, with await. Iterators are async: use ``async for``.

    It has 666 operations, on the routes under /v1/order.

    To start, list what the account has: list_carts, list_dedicated_clouds, list_freefaxes,
    list_over_the_boxes, list_sms, list_telephonies, list_veeam_cloud_connects, list_vps, and 278
    more.

    To find the method for a route, search index/order.jsonl: one line per method, with its route,
    its signature and the IAM actions it requires. It is at the root of the SDK repository, and in
    the installed package.
    """

    async def list_carts(self, *, description: str | None | NotGiven = NOT_GIVEN) -> list[str]:
        """list_carts calls GET /v1/order/cart: List of your OVH order carts

        Args:
            description: Filter the value of description property (=) (optional)

        Requires the IAM action order:apiovh:cart/get.
        """
        return await self._call(
            _r.OP_LIST_CARTS,
            query=(("description", description),),
            result=list[str],
        )

    async def create_cart(self, body: models.OrderCartCreation) -> models.OrderCartCart:
        """create_cart calls POST /v1/order/cart: Create a new OVH order cart

        Args:
            body: the request body
        """
        return await self._call(
            _r.OP_CREATE_CART,
            body=body,
            body_type=models.OrderCartCreation,
            result=models.OrderCartCart,
        )

    async def get_cart(self, cart_id: str) -> models.OrderCartCart:
        """get_cart calls GET /v1/order/cart/{cartId}: Retrieve information about a specific cart

        Args:
            cart_id: Cart ID
        """
        return await self._call(
            _r.OP_GET_CART,
            path_params={
                "cartId": cart_id,
            },
            result=models.OrderCartCart,
        )

    def all_carts(
        self, *, description: str | None | NotGiven = NOT_GIVEN
    ) -> t.AsyncIterator[models.OrderCartCart]:
        """all_carts iterates over GET /v1/order/cart (List of your OVH order carts).

        It lists the IDs with list_carts, then gets each object with get_cart,
        only when the loop reaches it. An object deleted in the meantime is skipped. Any other
        error is raised and stops the loop. Use it with ``async for``.

        Args:
            description: Filter the value of description property (=) (optional)

        The two calls require the IAM action order:apiovh:cart/get.
        """
        return self._each(
            lambda: self.list_carts(
                description=description,
            ),
            lambda listed_id: self.get_cart(listed_id),
        )

