    def all_cart_items(self, cart_id: str) -> t.AsyncIterator[models.OrderCartItem]:
        """all_cart_items iterates over GET /v1/order/cart/{cartId}/item (List all the items of a cart).

        It lists the IDs with list_cart_items, then gets each object with get_cart_item,
        only when the loop reaches it. An object deleted in the meantime is skipped. Any other
        error is raised and stops the loop. Use it with ``async for``.

        Args:
            cart_id: Cart ID
        """
        return self._each(
            lambda: self.list_cart_items(
                cart_id,
            ),
            lambda listed_id: self.get_cart_item(cart_id, listed_id),
        )

