    async def get_catalog_formatted_baremetal_servers(
        self,
        ovh_subsidiary: models.NichandleOvhSubsidiaryEnum | str,
        *,
        cores_max: int | None | NotGiven = NOT_GIVEN,
        cores_min: int | None | NotGiven = NOT_GIVEN,
        count: int | None | NotGiven = NOT_GIVEN,
        cpu_brands: list[str] | None | NotGiven = NOT_GIVEN,
        datacenters: list[str] | None | NotGiven = NOT_GIVEN,
        freq_max: float | None | NotGiven = NOT_GIVEN,
        freq_min: float | None | NotGiven = NOT_GIVEN,
        merge_generations: bool | None | NotGiven = NOT_GIVEN,
        offset: int | None | NotGiven = NOT_GIVEN,
        os_available: list[str] | None | NotGiven = NOT_GIVEN,
        plan_codes: str | None | NotGiven = NOT_GIVEN,
        price_max: float | None | NotGiven = NOT_GIVEN,
        price_min: float | None | NotGiven = NOT_GIVEN,
        private_bw_max: int | None | NotGiven = NOT_GIVEN,
        private_bw_min: int | None | NotGiven = NOT_GIVEN,
        public_bw_max: int | None | NotGiven = NOT_GIVEN,
        public_bw_min: int | None | NotGiven = NOT_GIVEN,
        ram_max: int | None | NotGiven = NOT_GIVEN,
        ram_min: int | None | NotGiven = NOT_GIVEN,
        ranges: list[str] | None | NotGiven = NOT_GIVEN,
        sockets: list[str] | None | NotGiven = NOT_GIVEN,
        sort: str | None | NotGiven = NOT_GIVEN,
        storage_max: float | None | NotGiven = NOT_GIVEN,
        storage_min: float | None | NotGiven = NOT_GIVEN,
        storage_raid: list[str] | None | NotGiven = NOT_GIVEN,
        storage_types: list[str] | None | NotGiven = NOT_GIVEN,
        threads_max: int | None | NotGiven = NOT_GIVEN,
        threads_min: int | None | NotGiven = NOT_GIVEN,
        use_cases: list[str] | None | NotGiven = NOT_GIVEN,
        with_gpu: bool | None | NotGiven = NOT_GIVEN,
    ) -> models.OrderCatalogFormattedBaremetalServersServerList:
        """get_catalog_formatted_baremetal_servers calls GET /v1/order/catalog/formatted/baremetalServers: List the servers of the public bare-metal catalog for a subsidiary

        Bare-metal dedicated servers of the public catalog for a subsidiary: one product per
        commercial server (its newest hardware generation by default, `mergeGenerations=false` lists
        every generation) with the specs of its default configuration, the ranges of its options and
        one price per datacenter, with hardware, network, price and range filters, sorting and
        pagination. Text specs and prices follow the website's typography for the subsidiary.

        Args:
            ovh_subsidiary: OVHcloud subsidiary targeted
            cores_max: Maximum number of CPU cores (optional)
            cores_min: Minimum number of CPU cores (optional)
            count: Number of results per page. Default to 20 (optional)
            cpu_brands: Filter on CPU brands (e.g. Intel, AMD). Repeat the parameter for multiple values (optional)
            datacenters: Filter on datacenters where the server is available. Repeat the parameter for multiple values (optional)
            freq_max: Maximum CPU frequency, in GHz (optional)
            freq_min: Minimum CPU frequency, in GHz (optional)
            merge_generations: Fold the hardware generations of a model into one server, the newest one extended with the datacenters only older generations still serve. Default to true; false lists every generation (optional)
            offset: Offset of the first result returned, used with count for pagination (optional)
            os_available: Filter on available operating systems. Repeat the parameter for multiple values (optional)
            plan_codes: Return only the servers with these plan codes, comma-separated (e.g. 25rise01,25adv01), matched case-insensitively (optional)
            price_max: Maximum monthly price, in the subsidiary currency (e.g. 499.99) (optional)
            price_min: Minimum monthly price, in the subsidiary currency (e.g. 99.99) (optional)
            private_bw_max: Maximum private bandwidth, in Mbps (optional)
            private_bw_min: Minimum private bandwidth, in Mbps (optional)
            public_bw_max: Maximum public bandwidth, in Mbps (optional)
            public_bw_min: Minimum public bandwidth, in Mbps (optional)
            ram_max: Maximum RAM size, in GB (optional)
            ram_min: Minimum RAM size, in GB (optional)
            ranges: Filter on commercial ranges. Repeat the parameter for multiple values (optional)
            sockets: Filter on the number of CPU sockets. Repeat the parameter for multiple values (optional)
            sort: Sort order: price-asc (default), price-desc, name-asc or name-desc. Servers with a promotion always come first (optional)
            storage_max: Maximum storage size, in GB (optional)
            storage_min: Minimum storage size, in GB (optional)
            storage_raid: Filter on RAID levels of the default storage configuration. Repeat the parameter for multiple values (optional)
            storage_types: Filter on storage types. Repeat the parameter for multiple values (optional)
            threads_max: Maximum number of CPU threads (optional)
            threads_min: Minimum number of CPU threads (optional)
            use_cases: Filter on server use cases. Repeat the parameter for multiple values (optional)
            with_gpu: Filter on servers with (true) or without (false) a GPU (optional)
        """
        return await self._call(
            _r.OP_GET_CATALOG_FORMATTED_BAREMETAL_SERVERS,
            query=(
                ("coresMax", cores_max),
                ("coresMin", cores_min),
                ("count", count),
                ("cpuBrands", cpu_brands),
                ("datacenters", datacenters),
                ("freqMax", freq_max),
                ("freqMin", freq_min),
                ("mergeGenerations", merge_generations),
                ("offset", offset),
                ("osAvailable", os_available),
                ("ovhSubsidiary", ovh_subsidiary),
                ("planCodes", plan_codes),
                ("priceMax", price_max),
                ("priceMin", price_min),
                ("privateBwMax", private_bw_max),
                ("privateBwMin", private_bw_min),
                ("publicBwMax", public_bw_max),
                ("publicBwMin", public_bw_min),
                ("ramMax", ram_max),
                ("ramMin", ram_min),
                ("ranges", ranges),
                ("sockets", sockets),
                ("sort", sort),
                ("storageMax", storage_max),
                ("storageMin", storage_min),
                ("storageRaid", storage_raid),
                ("storageTypes", storage_types),
                ("threadsMax", threads_max),
                ("threadsMin", threads_min),
                ("useCases", use_cases),
                ("withGpu", with_gpu),
            ),
            result=models.OrderCatalogFormattedBaremetalServersServerList,
        )

